$ErrorActionPreference = "Stop"

# 1) Remove broken junctions pointing at missing C:\devtool
foreach ($p in @("D:\devtool", "D:\devtools")) {
  $item = Get-Item $p -Force -ErrorAction SilentlyContinue
  if ($item -and $item.LinkType -eq "Junction") {
    Write-Host "Removing broken junction $p -> $($item.Target)"
    cmd /c "rmdir `"$p`""
    if ($LASTEXITCODE -ne 0) { throw "Failed to remove junction $p" }
  }
}

# 2) Create real D:\devtool
New-Item -ItemType Directory -Force -Path "D:\devtool" | Out-Null
New-Item -ItemType Directory -Force -Path "D:\devtool\npm-cache" | Out-Null

# 3) Compat junction so old D:\devtools paths keep working
cmd /c "mklink /J `"D:\devtools`" `"D:\devtool`""
if ($LASTEXITCODE -ne 0) { throw "Failed to create D:\devtools junction" }

Write-Host "OK layout:"
Get-Item "D:\devtool","D:\devtools" -Force | Format-Table FullName, Attributes, LinkType, Target -AutoSize
Get-ChildItem "D:\devtool" | Format-Table Name, Mode

