    $p = Get-Process -Id $c.ProcessId -ErrorAction SilentlyContinue
    Write-Host "child: $($c.Name) pid=$($c.ProcessId) cpu=$($p.CPU) memoryMB=$([math]::Round($p.WorkingSet64/1MB,1))"
    $grand = Get-CimInstance Win32_Process | Where-Object { $_.ParentProcessId -eq $c.ProcessId }
    foreach ($g in $grand) {
      $gp = Get-Process -Id $g.ProcessId -ErrorAction SilentlyContinue
      Write-Host "grandchild: $($g.Name) pid=$($g.ProcessId) cpu=$($gp.CPU) memoryMB=$([math]::Round($gp.WorkingSet64/1MB,1))"
    }
  }
} else { Write-Host "root process absent" }
